+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (constructorStrategy != null) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return __ -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionBasedFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; it must be a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private static String createDescriptionBasedFileName(String description) {
+        String retainedWord = findRetainedDescriptionWord(description);
+        String hash = sha256(description);
+        String prefix = retainedWord == null ? "rule" : retainedWord;
+        String result = prefix + "-" + hash;
+        // The selected word is at most 120 characters and SHA-256 is 64 hexadecimal
+        // characters, so this is defensive documentation of the invariant.
+        return result.substring(0, Math.min(200, result.length()));
+    }
+
+    private static String findRetainedDescriptionWord(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String result = null;
+        while (matcher.find()) {
+            String candidate = matcher.group();
+            if (result == null || candidate.length() > result.length()) {
+                result = candidate;
+            }
+        }
+        return result;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte valueByte : digest) {
+                result.append(String.format("%02x", valueByte & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException("JVM does not provide SHA-256", e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void prepareStoreFolderAndIndex(File storedRulesFile) {
+        Path folder = storeFolder.toPath();
+        try {
+            if (Files.exists(folder, LinkOption.NOFOLLOW_LINKS) && !Files.isDirectory(folder)) {
+                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", folder));
+            }
+            if (!Files.exists(folder, LinkOption.NOFOLLOW_LINKS)) {
+                if (!storeCreationAllowed) {
+                    throw storeCreationDisabled(storedRulesFile);
+                }
+                Files.createDirectories(folder);
+            }
+
+            Path index = storedRulesFile.toPath();
+            boolean indexExists = Files.exists(index, LinkOption.NOFOLLOW_LINKS);
+            if (indexExists && !Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The store index must be a regular file directly in the store folder: %s", index));
+            }
+            if (!indexExists && !storeCreationAllowed) {
+                throw storeCreationDisabled(storedRulesFile);
+            }
+            if (indexExists) {
+                storedRules.loadFrom(index.toFile());
+            } else {
+                storedRules.resetToEmpty();
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private StoreInitializationFailedException storeCreationDisabled(File storedRulesFile) {
+        return new StoreInitializationFailedException(String.format(
+                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+    }
+
+    private void syncIndexForInitialization() {
+        try {
+            storedRules.syncFileSystem();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (violations.isEmpty() && existingFileName == null) {
+                return;
+            }
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(description, existingFileName);
+            } else if (existingFileName != null) {
+                Path destination = writableExistingRuleFile(existingFileName);
+                write(violations, destination);
+            } else {
+                String newFileName = ruleFileName(description);
+                Path destination = newRuleFilePath(newFileName);
+                write(violations, destination);
+                boolean indexUpdated = false;
+                try {
+                    storedRules.putWithoutSync(description, newFileName);
+                    storedRules.syncFileSystem();
+                    indexUpdated = true;
+                } catch (IOException e) {
+                    storedRules.removeWithoutSync(description);
+                    throw new StoreUpdateFailedException(e);
+                } finally {
+                    if (!indexUpdated) {
+                        deleteQuietly(destination);
+                    }
+                }
+            }
+        }
+    }
+
+    private void forgetRule(String description, String fileName) {
+        Path entryPath = safeEntryPathForSave(fileName);
+        EntryFile entryFile = resolveEntryFile(fileName, entryPath);
+        if (entryFile.isUnsafe()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot forget rule '%s': its stored file is outside the store folder or is not a regular file directly in it",
+                    description));
+        }
+
+        if (!isSharedByAnotherEntry(description, entryFile)) {
+            try {
+                deleteEntryFile(entryFile);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.removeWithoutSync(description);
+        try {
+            storedRules.syncFileSystem();
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private boolean isSharedByAnotherEntry(String description, EntryFile entryFile) {
+        for (Map.Entry<String, String> entry : storedRules.entries()) {
+            if (entry.getKey().equals(description)) {
+                continue;
+            }
+            if (entry.getValue().equals(entryFile.fileName)) {
+                return true;
+            }
+            EntryFile other = resolveEntryFile(entry.getValue(), safeEntryPathForSave(entry.getValue()));
+            if (entryFile.resolvedPath != null && other.resolvedPath != null && entryFile.resolvedPath.equals(other.resolvedPath)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private String ruleFileName(String description) {
+        String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (fileName == null || fileName.trim().isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
+        }
+        return fileName;
+    }
+
+    private Path newRuleFilePath(String fileName) {
+        Path path = safeEntryPathForSave(fileName);
+        if (path == null || STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name '%s' is not a regular file directly in the store folder or names the store index",
+                    fileName));
+        }
+        try {
+            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to overwrite existing store file '%s'", fileName));
+            }
+        } catch (SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        return path;
+    }
+
+    private Path writableExistingRuleFile(String fileName) {
+        Path path = safeEntryPathForSave(fileName);
+        if (path == null || STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write rule file '%s' outside the store folder or over the store index", fileName));
+        }
+        try {
+            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                return path;
+            }
+            if (!Files.isRegularFile(path)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write rule file '%s' because it is not a regular file", fileName));
+            }
+            Path realPath = path.toRealPath();
+            if (!realPath.getParent().equals(realStoreFolderPath)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write rule file '%s' outside the store folder", fileName));
+            }
+            return realPath;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private Path safeEntryPathForSave(String fileName) {
+        if (fileName == null || fileName.trim().isEmpty()) {
+            return null;
+        }
+        try {
+            Path path = Paths.get(fileName);
+            path = (path.isAbsolute() ? path : storeFolderPath.resolve(path)).normalize();
+            return storeFolderPath.equals(path.getParent()) ? path : null;
+        } catch (InvalidPathException e) {
+            return null;
+        }
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        Path temporaryFile = null;
+        try {
+            temporaryFile = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
+            Files.write(temporaryFile, builder.toString().getBytes(UTF_8));
+            moveReplacing(temporaryFile, ruleDetails);
+            temporaryFile = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporaryFile != null) {
+                deleteQuietly(temporaryFile);
+            }
+        }
+    }
+
+    private void moveReplacing(Path source, Path destination) throws IOException {
+        try {
+            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+        } catch (AtomicMoveNotSupportedException e) {
+            Files.move(source, destination, StandardCopyOption.REPLACE_EXISTING);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
