/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can be configured through the following properties:
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
 * default.integrity=...          # ignore, repair, or fail
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern LINE_BREAKS_ONLY_PATTERN = Pattern.compile("[\\r\\n]+");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])[A-Za-z0-9]{4,120}(?![A-Za-z0-9])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_RANDOM = "random";
    private static final String FILE_NAMES_DESCRIPTION = "description";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";

    /*
     * The value is deliberately shared by all store instances for one path. Besides making
     * Properties updates safe, this is the lock which makes an integrity scan atomic with
     * respect to saves made by another store in this JVM.
     */
    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;

    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private boolean randomFileNames;
    private IntegrityMode integrityMode;
    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private Path storeFolderPath;
    private Path realStoreFolderPath;
    private FileSyncedProperties storedRules;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        constructorStrategy = checkNotNull(ruleViolationFileNameStrategy);
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        ruleViolationFileNameStrategy = configureFileNameStrategy(properties);

        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        storeFolderPath = storeFolder.toPath().toAbsolutePath().normalize();
        File storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());

        storedRules = getOrCreateStoredRules(storedRulesFile);
        synchronized (storedRules) {
            prepareStoreFolderAndIndex(storedRulesFile);
            try {
                realStoreFolderPath = storeFolderPath.toRealPath();
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }

            boolean indexWasAbsent = !Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
            if (integrityMode == IntegrityMode.IGNORE) {
                if (indexWasAbsent) {
                    syncIndexForInitialization();
                }
                return;
            }

            IntegrityReport report = inspectIntegrity();
            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
                throw new StoreInitializationFailedException(report.asMessage());
            }
            if (integrityMode == IntegrityMode.REPAIR) {
                boolean changed = repair(report);
                if (changed) {
                    syncIndexForInitialization();
                }
            }
            // Creation is deliberately delayed until after a fail-mode scan. Thus a
            // rejected initialization never creates an absent index.
            if (indexWasAbsent && integrityMode == IntegrityMode.FAIL || indexWasAbsent && integrityMode == IntegrityMode.REPAIR) {
                syncIndexForInitialization();
            }
        }
    }

    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
        if (constructorStrategy != null) {
            randomFileNames = false;
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
        if (FILE_NAMES_RANDOM.equals(configured)) {
            randomFileNames = true;
            return __ -> UUID.randomUUID().toString();
        }
        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
            randomFileNames = false;
            return TextFileBasedViolationStore::createDescriptionBasedFileName;
        }
        randomFileNames = false;
        try {
            Class<?> strategyType = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyType.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s=%s; it must be a RuleViolationFileNameStrategy with a public no-argument constructor",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }
    }

    private static String createDescriptionBasedFileName(String description) {
        String retainedWord = findRetainedDescriptionWord(description);
        String hash = sha256(description);
        String prefix = retainedWord == null ? "rule" : retainedWord;
        String result = prefix + "-" + hash;
        // The selected word is at most 120 characters and SHA-256 is 64 hexadecimal
        // characters, so this is defensive documentation of the invariant.
        return result.substring(0, Math.min(200, result.length()));
    }

    private static String findRetainedDescriptionWord(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String result = null;
        while (matcher.find()) {
            String candidate = matcher.group();
            if (result == null || candidate.length() > result.length()) {
                result = candidate;
            }
        }
        return result;
    }

    private static String sha256(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
            StringBuilder result = new StringBuilder(digest.length * 2);
            for (byte valueByte : digest) {
                result.append(String.format("%02x", valueByte & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("JVM does not provide SHA-256", e);
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
        try {
            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void prepareStoreFolderAndIndex(File storedRulesFile) {
        Path folder = storeFolder.toPath();
        try {
            if (Files.exists(folder, LinkOption.NOFOLLOW_LINKS) && !Files.isDirectory(folder)) {
                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", folder));
            }
            if (!Files.exists(folder, LinkOption.NOFOLLOW_LINKS)) {
                if (!storeCreationAllowed) {
                    throw storeCreationDisabled(storedRulesFile);
                }
                Files.createDirectories(folder);
            }

            Path index = storedRulesFile.toPath();
            boolean indexExists = Files.exists(index, LinkOption.NOFOLLOW_LINKS);
            if (indexExists && !Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The store index must be a regular file directly in the store folder: %s", index));
            }
            if (!indexExists && !storeCreationAllowed) {
                throw storeCreationDisabled(storedRulesFile);
            }
            if (indexExists) {
                storedRules.loadFrom(index.toFile());
            } else {
                storedRules.resetToEmpty();
            }
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private StoreInitializationFailedException storeCreationDisabled(File storedRulesFile) {
        return new StoreInitializationFailedException(String.format(
                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
