    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && existingFileName == null && integrityMode == IntegrityMode.REPAIR) {
                return;
            }
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                forgetRule(description, existingFileName);
            } else if (existingFileName != null) {
                Path destination = writableExistingRuleFile(existingFileName);
                write(violations, destination);
            } else {
                String newFileName = ruleFileName(description);
                Path destination = newRuleFilePath(newFileName);
                write(violations, destination);
                boolean indexUpdated = false;
                try {
                    storedRules.putWithoutSync(description, newFileName);
                    storedRules.syncFileSystem();
                    indexUpdated = true;
                } catch (IOException e) {
                    storedRules.removeWithoutSync(description);
                    throw new StoreUpdateFailedException(e);
                } finally {
                    if (!indexUpdated) {
                        deleteQuietly(destination);
                    }
                }
            }
        }
    }

    private void forgetRule(String description, String fileName) {
        Path entryPath = safeEntryPathForSave(fileName);
        EntryFile entryFile = resolveEntryFile(fileName, entryPath);
        if (entryFile.isUnsafe()) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot forget rule '%s': its stored file is outside the store folder or is not a regular file directly in it",
                    description));
        }

        if (!isSharedByAnotherEntry(description, entryFile)) {
            try {
                deleteEntryFile(entryFile);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
        storedRules.removeWithoutSync(description);
        try {
            storedRules.syncFileSystem();
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private boolean isSharedByAnotherEntry(String description, EntryFile entryFile) {
        for (Map.Entry<String, String> entry : storedRules.entries()) {
            if (entry.getKey().equals(description)) {
                continue;
            }
            if (entry.getValue().equals(entryFile.fileName)) {
                return true;
            }
            EntryFile other = resolveEntryFile(entry.getValue(), safeEntryPathForSave(entry.getValue()));
            if (entryFile.resolvedPath != null && other.resolvedPath != null && entryFile.resolvedPath.equals(other.resolvedPath)) {
                return true;
            }
        }
        return false;
    }

