    private Path newRuleFilePath(String fileName) {
        Path path = safeEntryPathForSave(fileName);
        if (path == null || STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' is not a regular file directly in the store folder or names the store index",
                    fileName));
        }
        try {
            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to overwrite existing store file '%s'", fileName));
            }
        } catch (SecurityException e) {
            throw new StoreUpdateFailedException(e);
        }
        return path;
    }

    private Path writableExistingRuleFile(String fileName) {
        Path path = safeEntryPathForSave(fileName);
        if (path == null || STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write rule file '%s' outside the store folder or over the store index", fileName));
        }
        try {
            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                return path;
            }
            if (!Files.isRegularFile(path)) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to write rule file '%s' because it is not a regular file", fileName));
            }
            Path realPath = path.toRealPath();
            if (!realPath.getParent().equals(realStoreFolderPath)
                    || realPath.equals(realStoreFolderPath.resolve(STORED_RULES_FILE_NAME))) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to write rule file '%s' outside the store folder or over the store index", fileName));
            }
            return realPath;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private Path safeEntryPathForSave(String fileName) {
        if (fileName == null || fileName.trim().isEmpty()) {
            return null;
        }
        try {
            Path path = Paths.get(fileName);
            path = (path.isAbsolute() ? path : storeFolderPath.resolve(path)).normalize();
            return storeFolderPath.equals(path.getParent()) ? path : null;
        } catch (InvalidPathException e) {
            return null;
        }
    }

    private void write(List<String> violations, Path ruleDetails) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        Path temporaryFile = null;
        try {
            temporaryFile = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
